import styles from "./index.module.scss";

export default function ImpactMetrics({ mertics }) {
  return (
    <div className="container">
      <div className="row">
        {mertics.map((insight, index) => (
          <div key={index} className={`${styles.mertics} col-sm-12 col-lg-4 pe-lg-0 flex-fill}`}>
            <section className="mb-3">
              <h4 className="mb-3">{insight.title}</h4>
              <h1 className="">{insight.metric}</h1>
            </section>
          </div>
        ))}
      </div>
    </div>
  );
}
